// SAFE — React escapes all expressions by default
function Comment({ text }: { text: string }) {
  // If text = '<script>alert(1)</script>'
  // React renders it as the literal string, not as HTML
  return <p>{text}</p>;
  // Rendered: <p>&lt;script&gt;alert(1)&lt;/script&gt;</p>
}

// DANGEROUS — dangerouslySetInnerHTML bypasses React's escaping
function RichComment({ html }: { html: string }) {
  // If html contains <script> or <img onerror=...>, it RUNS
  return <div dangerouslySetInnerHTML={{ __html: html }} />;
  // XSS is possible — only use with sanitized HTML
}

// SAFE usage of dangerouslySetInnerHTML — sanitize first
import DOMPurify from 'dompurify';

function SafeRichComment({ html }: { html: string }) {
  const clean = DOMPurify.sanitize(html);  // Strips dangerous tags/attrs
  return <div dangerouslySetInnerHTML={{ __html: clean }} />;
}

// OTHER DANGEROUS PATTERNS IN REACT:
// href injection — if href comes from user input:
const url = userInput;  // 'javascript:alert(1)' is a valid URL!
return <a href={url}>Click</a>;  // XSS via javascript: protocol

// SAFE — validate URL scheme
const safeUrl = url.startsWith('http') ? url : '#';
return <a href={safeUrl}>Click</a>;

// When rendering HTML on the server (SSR, templates, email)
// EVERY user-provided value must be HTML-encoded before insertion

// VULNERABLE — template string with raw user data
const html = `<h1>Hello, ${req.query.name}!</h1>`;
// If name = '<script>alert(1)</script>'
// Rendered: <h1>Hello, <script>alert(1)</script>!</h1>  ← XSS

// SAFE — HTML-encode the value
function htmlEncode(str: string): string {
  return str
    .replace(/&/g, '&amp;')   // Must be first!
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

const html = `<h1>Hello, ${htmlEncode(req.query.name)}!</h1>`;
// If name = '<script>alert(1)</script>'
// Rendered: <h1>Hello, &lt;script&gt;alert(1)&lt;/script&gt;!</h1>
// Browser displays: Hello, <script>alert(1)</script>!
// No script runs.

// In practice, use a templating engine that auto-escapes:
// Handlebars: {{name}}         ← auto-escaped
//             {{{name}}}       ← raw, not escaped (dangerous)
// EJS:        <%= name %>      ← auto-escaped
//             <%- name %>      ← raw, not escaped (dangerous)
